script:
card({
  name: 'Lane race',
  icon: 'run',
  mode: 'lanes',
  players: { min: 2, max: 6 },
  match: { bestOf: 3 },
  permissions: ['keyboard', 'sound'],
  keys: { ArrowRight: 'step', Space: 'step' },
});

const finish = 20;

on.step = (state, args, ctx) => {
  if (state.match && state.match.winner) throw 'The match is over';
  const round = state.match ? state.match.round : 1;
  // A new round starts everyone at the start line.
  if (ctx.lane.round !== round) {
    ctx.lane.round = round;
    ctx.lane.pos = 0;
  }
  ctx.lane.name = ctx.authorName;
  ctx.lane.pos += 1;
  if (ctx.lane.pos >= finish) {
    ctx.sound('win');
    ctx.endRound(ctx.author);
  }
};

function init(ctx) {
  return { lanes: {} };
}

function view(state, me, now, local) {
  const round = state.match ? state.match.round : 1;
  const wins = state.match ? state.match.wins : {};
  const rows = Object.keys(state.lanes).map(id => {
    const lane = state.lanes[id];
    const pos = lane.round === round ? lane.pos : 0;
    return column([
      row([text(lane.name + (id === me.id ? ' (you)' : '')), badge((wins[id] || 0) + ' won')]),
      progress(pos / finish),
    ]);
  });
  if (state.match && state.match.winner) {
    rows.push(text(state.lanes[state.match.winner].name + ' wins the match!', { bold: true, align: 'center' }));
  }
  return column([
    text('Round ' + round + ' · first to ' + finish, { tone: 'muted', align: 'center' }),
    ...rows,
    button('Step →', 'step', null, { tone: 'accent' }),
  ]);
}

function pause(local, ctx) {
  local.away = true;
}

function resume(local, ctx) {
  local.away = false;
}
